A='<span aria-hidden="true">↗</span>'
def link(url,label,cls='button'):
 return f'<a class="{cls}" href="{{{{url:{url}}}}}">{label} {A}</a>'
def intro(eyebrow,title,text):
 return f'<section class="page-hero wrap"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lead">{text}</p></section>'
def cta():
 return f'<section class="cta wrap"><div><p class="eyebrow">LET’S MAKE PROGRESS</p><h2>Your next chapter.<br>Built together.</h2></div><div><p>Bring us your challenge. We’ll help you find a practical way forward.</p>{link("start-a-project","Let’s talk about your project","button light")}</div></section>'
def service_cards(items):
 return '<div class="service-grid">'+''.join(f'<a class="service-card" href="{{{{url:services/{s[0]}}}}}"><span class="card-top"><span class="index">{s[5]}</span>{A}</span><h3>{s[1]}</h3><p>{s[3]}</p><span class="text-link">Explore service <span aria-hidden="true">→</span></span></a>' for s in items)+'</div>'
pages={}
def page(slug,title,desc,body):pages[slug]={'title':title,'description':desc,'html':body}
