page('how-we-work','How we work','Discover our UK-led, Africa-connected delivery model and flexible engagement options.',intro('HOW WE WORK','One team.<br><em>From idea to impact.</em>','Good delivery comes from shared understanding, clear ownership and frequent, honest communication.')+'''<section class="wrap model-banner"><div><span class="eyebrow">UK CLIENT LEADERSHIP</span><h2>Context.<br>Accountability.<br>Partnership.</h2></div><span class="model-plus" aria-hidden="true">＋</span><div><span class="eyebrow">AFRICAN ENGINEERING</span><h2>Ingenuity.<br>Craft.<br>Commitment.</h2></div></section><section class="section wrap"><p class="eyebrow">THE DELIVERY JOURNEY</p><h2>Clarity at every step.</h2><div class="process-grid">'''+''.join(f'<article><span class="index">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate([('Discover','Understand the problem, users, constraints and measures of success.'),('Define','Agree scope, architecture, delivery approach and responsibilities.'),('Deliver','Build in visible increments, with reviews, testing and shared decisions.'),('Evolve','Launch with a handover, support plan and prioritised next steps.')]))+'''</div></section><section class="section tint"><div class="wrap"><p class="eyebrow">WAYS TO WORK TOGETHER</p><h2>A model that fits the work.</h2><div class="three-grid">'''+''.join(f'<article class="plain-card"><h3>{a}</h3><p>{b}</p></article>' for a,b in [('Discovery & advisory','A focused engagement to turn uncertainty into an actionable plan.'),('Project delivery','An agreed scope delivered by a dedicated team, with milestones and acceptance criteria.'),('Dedicated teams','Additional engineering capacity integrated with your people, tools and priorities.')])+'''</div></div></section><section class="section wrap faq"><div><p class="eyebrow">GOOD QUESTIONS</p><h2>Working together,<br>made clear.</h2></div><div>'''+''.join(f'<details><summary>{q}<span aria-hidden="true">＋</span></summary><p>{a}</p></details>' for q,a in [('Who will I work with?','We agree a named delivery lead and a team suited to the work before the engagement starts. UK coordination connects your stakeholders with the engineering team.'),('How do you handle time zones?','We agree shared working hours, review sessions and escalation routes at the start. The aim is meaningful collaboration with room for focused engineering.'),('How do you approach security and IP?','Access, confidentiality, intellectual property, data handling and any cross-border requirements are agreed contractually before delivery. Controls must match the specific project.'),('Can you work with our existing technology?','We assess your stack and requirements first, then propose engineers with relevant skills. We will be clear about any capability gaps or specialist partners needed.'),('Do you use AI-assisted coding?','Where appropriate, with client agreement. Engineers remain responsible for architecture, review, testing, security and the final deliverable. Sensitive client material must only be used with approved tools and settings.')])+'</div></section>'+cta())
page('about','About SIT Technology','UK leadership and African engineering talent working together to create practical technology solutions.',intro('ABOUT SIT TECHNOLOGY','Different perspectives.<br><em>Shared possibility.</em>','We’re building a technology consulting and engineering company that connects ambitious organisations with African technical talent.')+'''<section class="wrap about-story"><h2>A bridge between<br>talent and opportunity.</h2><div><p class="lead">Headquartered in the United Kingdom, with developers in Africa including Liberia, SIT Technology brings people together around meaningful work.</p><p>Our focus is practical: understand your challenge, assemble the right expertise and deliver technology that helps your organisation move forward.</p><p>We believe the best partnerships create lasting capability. That means sharing knowledge, developing engineers and making sure your team can own what we build together.</p></div></section><section class="section tint"><div class="wrap"><p class="eyebrow">WHAT GUIDES US</p><h2>Good work starts with good principles.</h2><div class="three-grid">'''+''.join(f'<article class="plain-card"><span class="index">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate([('Be clear','Open communication, honest estimates and visible progress.'),('Care about the craft','Thoughtful engineering, useful design and quality built into delivery.'),('Grow together','Create opportunity, share knowledge and build lasting capability.')]))+'</div></div></section>'+cta())
articles=[('ai-with-engineering-discipline','AI & ENGINEERING','Fast prototypes. Thoughtful production.','How we think about AI-assisted development without losing engineering discipline.','AI can help teams explore an idea quickly. A useful prototype still needs a deliberate path into production.', [('Start with a real problem','Define who the product serves, what decision or task it improves and how you will judge whether it helps. A compelling demo is a starting point, not an acceptance test.'),('Keep engineers accountable','Generated code deserves the same review as any other contribution. Teams should understand the design, check dependencies, test failure paths and review how data moves through the system.'),('Agree the boundaries','Decide which tools are approved, what data they may access and where human review is required. Document limitations and keep the final system understandable to the people who will maintain it.')]),('a-better-project-brief','DELIVERY','A better brief is a better beginning.','Five things that make your first project conversation more useful.','You do not need every answer before speaking to an engineering partner. A few clear starting points make the conversation more productive.', [('Explain the challenge','Describe what happens today, who is affected and why a change matters. Include examples from the people doing the work.'),('Share your constraints','Talk openly about timelines, budget ranges, existing systems and dependencies. These shape the options and help a partner make useful trade-offs.'),('Define a useful outcome','Describe what should be different when the work is complete. Agree who will make decisions, review progress and accept the deliverables.')])]
page('insights','Insights','Ideas and practical perspectives from SIT Technology.',intro('PERSPECTIVES','Ideas worth<br><em>building on.</em>','Practical thinking on technology, engineering and working better together.')+'<section class="wrap section compact"><div class="insight-grid">'+''.join(f'<a class="insight-card" href="{{{{url:insights/{a[0]}}}}}"><div class="insight-art art-{i}" aria-hidden="true"><span>{"{ }" if i==0 else "↗"}</span><small>{"ENGINEER THE NEXT" if i==0 else "BEGIN WITH CLARITY"}</small></div><p class="eyebrow">{a[1]} · SIT PERSPECTIVE</p><h2>{a[2]}</h2><p>{a[3]}</p><span class="text-link">Read the perspective →</span></a>' for i,a in enumerate(articles))+'</div></section>'+cta())
